mapper.select:
SELECT s.id, s.name, s.main_image, s.category_id, s.status, s.sales, p.price, p.market_price FROM t_spu s LEFT JOIN ( SELECT spu_id, price, market_price FROM ( SELECT spu_id, price, market_price, ROW_NUMBER() OVER (PARTITION BY spu_id ORDER BY price ASC, id ASC) AS rn FROM t_sku WHERE deleted = 0 ) lowest WHERE lowest.rn = 1 ) p ON p.spu_id = s.id WHERE s.deleted = 0
AND s.status = #{status}
AND s.category_id = #{categoryId}
AND s.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY s.id DESC
